import { _decorator, Component, Node, ScrollView } from 'cc';
import { FullView } from '../../scripts/Tea/UI/UIView';
import { Path } from '../../scripts/Tea/decorators/tea.decorators';
const { ccclass, property } = _decorator;

@ccclass('SelectLevelView')
export class SelectLevelView extends FullView {
    @Path('BackBtn')
    backBtn: Node = null!;
    @Path('ScrollView', ScrollView)
    scrollView: ScrollView = null!;

    onMount(): void {
        this.backBtn.on(Node.EventType.TOUCH_END, this.onClickBackBtn.bind(this));
    }

    onClickBackBtn(e){
        this.back();
    }
}


